//! 🧪️ Sequence comparison uses one real Source, finite Work bank and borrowed producer.
use semio_framework_value_equality::retained_equality::{RetainedEquality,RetainedEqualityCursor,RetainedEqualityStep,sequence::RetainedSequenceEquality};
use semio_framework_value_retained_clone::*;
use semio_framework_value_clone_source_testing::{FixtureSourceBirth,FixtureCloseStep};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use std::mem::ManuallyDrop;
type Input<T>=(Vec<T>,Vec<T>);
#[derive(Clone,Copy,PartialEq,Eq)]enum Op{Advance,Start,Close}
struct Context<'a,T:RetainedEquality+RetainedClone>{source:RetainedCloneRef<'a,Input<T>>,turn:OriginalSourceTurnIdentity,op:Op,body:usize,maximum:u64}
struct Producer<T:RetainedEquality+RetainedClone>{cursor:ManuallyDrop<RetainedSequenceEquality<T>>,source:(u64,usize,usize,usize),turn:OriginalSourceTurnIdentity,selected:Option<(OriginalEffectInvocationIdentity,Op,usize,u64)>,close_reply:ManuallyDrop<Option<Result<RetainedCloneStep,OriginalRetirementFailure>>>}
impl<T:RetainedEquality+RetainedClone> Producer<T>{fn empty(&self)->bool{self.selected.is_none()&&self.close_reply.is_none()&&<RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::terminal_is_empty(&self.cursor)}
 fn dispatch<'r>(&mut self,c:&mut Context<'_,T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedEqualityStep,OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'r,RetainedEqualityStep,OriginalRetirementFailure>,ValueError>{let invocation=effect.invocation().ok_or_else(||ValueError::invariant("sequence law invocation absent"))?;let mode=if recover{OriginalEffectCallbackMode::Recover}else{OriginalEffectCallbackMode::Receive};if invocation.mode()!=mode{return Err(ValueError::invariant("sequence law invocation changed"))}let key=(invocation.identity(),c.op,c.body,c.maximum);if recover{if self.selected!=Some(key){return Err(ValueError::invariant("sequence law request changed"))}}else if self.selected.is_some(){return Err(ValueError::invariant("sequence law action occupied"))}let mut scope=reply.scope(&mut self.selected,key)?;if c.op==Op::Advance{let input=c.source.get();let done=if recover{self.cursor.recover_advance_into(&input.0,&input.1,c.body,c.maximum,effect,scope.borrow()?)?}else{self.cursor.advance_into(&input.0,&input.1,c.body,c.maximum,effect,scope.borrow()?)?};drop(done);return Ok(scope.forwarded())}if self.close_reply.is_none(){let inner=OriginalEffectReply::borrow(&mut *self.close_reply)?;let done=match(c.op,recover){(Op::Start,false)=><RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::begin_close_into(&mut self.cursor,effect,inner)?,(Op::Start,true)=><RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::recover_begin_close_into(&mut self.cursor,effect,inner)?,(Op::Close,false)=><RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::close_into(&mut self.cursor,c.body,effect,inner)?,(Op::Close,true)=><RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::recover_close_into(&mut self.cursor,c.body,effect,inner)?,_=>unreachable!()};drop(done)}match self.close_reply.take(){Some(Ok(step))=>{let done=scope.borrow()?.complete(Ok(RetainedEqualityStep{equal:None,progress:step.progress()}));drop(done)},Some(Err(error))=>{let done=scope.borrow()?.complete(Err(error));drop(done)},None=>{}}Ok(scope.forwarded())}}
impl<T:RetainedEquality+RetainedClone> Drop for Producer<T>{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.empty());unsafe{ManuallyDrop::drop(&mut self.cursor);ManuallyDrop::drop(&mut self.close_reply)}}}
impl<T:RetainedEquality+RetainedClone> OriginalEffectProducer for Producer<T>{type Output=RetainedEqualityStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a,T> where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.source.reference_identity()!=self.source||c.turn!=self.turn{return Err(ValueError::invariant("sequence law changed original Source"))}Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn)}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,false)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,true)}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn run_case<T:RetainedEquality+RetainedClone>(left:Vec<T>,right:Vec<T>,expected:bool,cut:Option<usize>)->bool{let mut source=RetainedCloneSource::<Input<T>>::from_owner((left,right));let id=source.borrow().reference_identity();let mut authority=None;source.with_bank(|_,bank|{let (turn,actual)=bank.run_with_source(RetainedCloneGrant::default(),0,|_,witness|{authority=Some(OriginalEffectAuthority::new(Producer{cursor:ManuallyDrop::new(RetainedSequenceEquality::new()),source:id,turn:witness.identity(),selected:None,close_reply:ManuallyDrop::new(None)}));RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0})});assert!(matches!(turn,RetainedWorkPoll::Complete(_)));assert!(actual.is_none());}).unwrap();let mut action=None;let mut result=None;let mut op=Op::Advance;let mut equal=None;let mut advance_turns=0usize;let mut cancelled=false;for _ in 0..256{if op==Op::Advance&&cut.is_some_and(|cut|advance_turns>=cut){cancelled=true;op=Op::Start}let producer=authority.as_ref().unwrap();if op==Op::Close&&producer.inspect(Producer::<T>::empty){break}let(d,work)=producer.inspect(|p|match op{Op::Advance=>(<RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::demand(&p.cursor,4096,4096).unwrap(),<RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::work_demand(&p.cursor,4096,4096).unwrap()),Op::Start=>(<RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::begin_close_demand(&p.cursor).unwrap(),<RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::begin_close_work_demand(&p.cursor).unwrap()),Op::Close=>(<RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::close_demand(&p.cursor,4096).unwrap(),<RetainedSequenceEquality<T> as RetainedEqualityCursor<Vec<T>>>::close_work_demand(&p.cursor,4096).unwrap())});let ((poll,actual),heap)=source.with_bank(|original,bank|{let grant=grant(d);let observed=observe(||bank.run_with_source(grant,work,|effect,witness|{let before=effect.performed_work();let mut context=Context{source:original,turn:witness.identity(),op,body:4096,maximum:4096};let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}else{RetainedWorkPoll::Pending{work:effect.performed_work()-before}}}));let((ref poll,_),observed_heap)=observed;if matches!(poll,RetainedWorkPoll::Complete(_)){assert!(action.as_mut().unwrap().transfer_reply(&mut result).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=result.as_ref().unwrap().as_ref().unwrap();assert_eq!(observed_heap,(step.progress.retained_capacity_bytes,step.progress.released_bytes));assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress,grant,observed_heap);}observed}).unwrap();let RetainedWorkPoll::Complete(turn)=poll else{panic!("sequence action remained pending")};turn.result.unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}let step=result.take().unwrap().unwrap();if op==Op::Advance{advance_turns+=1}if op==Op::Advance&&step.equal.is_some(){equal=step.equal;op=Op::Start}else if op==Op::Start{op=Op::Close}}if cut.is_none()||equal.is_some(){assert_eq!(equal,Some(expected))}assert!(authority.as_ref().unwrap().inspect(Producer::<T>::empty));
 source.with_bank(|original,bank|{let d=OriginalEffectAuthority::<Producer<T>>::producer_transfer_demand().unwrap();let first_grant=grant(d);let mut producer=None;let((poll,_),heap)=observe(||bank.run_with_source(first_grant,1,|effect,witness|{let context=Context{source:original,turn:witness.identity(),op:Op::Close,body:0,maximum:0};RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&context,&mut producer,effect))}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("producer transfer pending")};let progress=turn.result.unwrap().unwrap();assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,first_grant,heap);let witness=unsafe{RetainedCursorRelease::native(Producer::<T>::empty)};assert!(witness.validates(producer.as_ref().unwrap()));let d=witness.inline_demand();let grant=grant(d);let mut reply=None;let((poll,_),heap)=observe(||bank.run(grant,1,|effect|{let before=effect.performed_work();let token=OriginalEffectReply::borrow(&mut reply).unwrap();drop(witness.inline_into(&mut producer,effect,token).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));let step=reply.take().unwrap().unwrap();assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap);}).unwrap();for _ in 0..10000{if source.terminal_is_empty(){break}match source.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("source close refused"),_=>{}}}assert!(source.terminal_is_empty());cancelled}
#[test]fn original_sequence_compares_and_closes_on_one_finite_source(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();for row in law["comparisons"].as_array().unwrap(){let bytes=|key:&str|row[key].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect::<Vec<_>>();run_case(bytes("left"),bytes("right"),row["equal"].as_bool().unwrap(),None);let mut later=false;for cut in law["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let reached=run_case(bytes("left"),bytes("right"),row["equal"].as_bool().unwrap(),Some(cut));if cut==0{assert!(reached)}else{later|=reached}}assert!(later)}}
#[test]fn original_nested_strings_keep_their_typed_children_and_source(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();for row in law["nestedComparisons"].as_array().unwrap(){let values=|key:&str|row[key].as_array().unwrap().iter().map(|n|n.as_str().unwrap().to_owned()).collect::<Vec<_>>();run_case(values("left"),values("right"),row["equal"].as_bool().unwrap(),None);let mut later=false;for cut in law["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let reached=run_case(values("left"),values("right"),row["equal"].as_bool().unwrap(),Some(cut));if cut==0{assert!(reached)}else{later|=reached}}assert!(later)}}
